begin;
select plan(16);
select lives_ok($test$select private.validate_organization_presentation('{}'::jsonb)$test$,'Existing default config remains valid');
select lives_ok($test$select private.validate_organization_presentation('{"logo":"data:image/png;base64,SGk="}'::jsonb)$test$,'Existing shared logo remains valid');
select lives_ok($test$select private.validate_organization_presentation('{"logoOnLight":"data:image/jpeg;base64,SGk=","logoOnDark":"data:image/webp;base64,SGk="}'::jsonb)$test$,'Independent light and dark logos validate');
select lives_ok($test$select private.validate_organization_presentation('{"logo":null,"logoOnLight":null,"logoOnDark":null}'::jsonb)$test$,'Cleared logo variants preserve defaults');
select throws_ok($test$select private.validate_organization_presentation('{"logoOnLight":"https://example.test/logo.png"}'::jsonb)$test$,'PT400',null,'Light logo rejects external URL');
select throws_ok($test$select private.validate_organization_presentation('{"logoOnDark":"https://example.test/logo.png"}'::jsonb)$test$,'PT400',null,'Dark logo rejects external URL');
select throws_ok($test$select private.validate_organization_presentation('{"logoOnLight":true}'::jsonb)$test$,'PT400',null,'Light logo rejects nonstring');
select throws_ok($test$select private.validate_organization_presentation('{"logoOnDark":"data:text/html;base64,SGk="}'::jsonb)$test$,'PT400',null,'Dark logo rejects other MIME types');
select throws_ok($test$select private.validate_organization_presentation('{"logoOther":null}'::jsonb)$test$,'PT400',null,'Unknown configuration fields remain rejected');
select throws_ok($test$select private.validate_organization_presentation(jsonb_build_object('logoOnLight','data:image/png;base64,'||repeat('A',1600000),'logoOnDark','data:image/png;base64,'||repeat('A',1600000)))$test$,'PT400',null,'Total configuration size stays capped');
select throws_ok($test$select private.validate_organization_presentation(jsonb_build_object('logoOnLight','data:image/png;base64,'||repeat('A',2800000)))$test$,'PT400',null,'Light logo individual size stays capped');
select throws_ok($test$select private.validate_organization_presentation(jsonb_build_object('logoOnDark','data:image/png;base64,'||repeat('A',2800000)))$test$,'PT400',null,'Dark logo individual size stays capped');
select throws_ok($test$select private.validate_organization_presentation('{"logo":"https://example.test/logo.png"}'::jsonb)$test$,'PT400',null,'Shared logo validation remains unchanged');
select ok(not has_function_privilege('authenticated','private.validate_organization_presentation(jsonb)','EXECUTE'),'Validator remains private to authenticated users');
select ok(not has_function_privilege('anon','private.validate_organization_presentation(jsonb)','EXECUTE'),'Validator remains private to anonymous users');
select ok(not has_function_privilege('anon','public.save_organization_presentation(uuid,uuid,bigint,jsonb)','EXECUTE'),'Anonymous settings writes remain unavailable');
select * from finish();
rollback;
